import{_ as n,C as s,o as e,c as u,j as i,E as r,a as l,a2 as t}from"./chunks/framework.C21TwvGF.js";const P=JSON.parse(`{"title":"2-dars (Mentor). IoT arxitekturasi: Sensorlar, aktuatorlar va apparat ta'minoti","description":"","frontmatter":{"title":"2-dars (Mentor). IoT arxitekturasi: Sensorlar, aktuatorlar va apparat ta'minoti","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (IoT)","link":"/mentor/9-sinf-iot/"},"week":{"n":1,"link":"/mentor/9-sinf-iot/hafta-01/"},"g":2,"title":"IoT arxitekturasi: Sensorlar, aktuatorlar va apparat ta'minoti","lead":"IoT arxitekturasi: Sensorlar, aktuatorlar va apparat ta'minoti","slide":"/slaydlar/9-sinf-iot/hafta-01/dars-2.html","test":"/slaydlar/9-sinf-iot/hafta-01/dars-2-test.html","student_link":"/9-sinf-iot/hafta-01/dars-2","tabs":[{"g":1,"link":"/mentor/9-sinf-iot/hafta-01/dars-1","current":false},{"g":2,"link":"/mentor/9-sinf-iot/hafta-01/dars-2","current":true},{"g":3,"link":"/mentor/9-sinf-iot/hafta-01/dars-3","current":false}],"prev":{"g":1,"title":"IoT tushunchasi va qo‘llanish sohalari","link":"/mentor/9-sinf-iot/hafta-01/dars-1"},"next":{"g":3,"title":"IoT arxitekturasi: Tarmoq, bulut va foydalanuvchi interfeysi","link":"/mentor/9-sinf-iot/hafta-01/dars-3"}}},"headers":[],"relativePath":"mentor/9-sinf-iot/hafta-01/dars-2.md","filePath":"mentor/9-sinf-iot/hafta-01/dars-2.md"}`),m={name:"mentor/9-sinf-iot/hafta-01/dars-2.md"},h={class:"blk"},d={id:"dars-rejasi",tabindex:"-1"},k={class:"blk"},g={id:"mentor-konspekti",tabindex:"-1"},q={class:"blk"},v={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},y={class:"blk"},b={id:"tezkor-nazorat-savollari",tabindex:"-1"},p={class:"blk"},c={id:"keng-tarqalgan-xatolar-va-ularning-oldini-olish",tabindex:"-1"};function z(f,a,x,_,T,A){const o=s("Icon");return e(),u("div",null,[i("div",h,[i("h2",d,[r(o,{name:"file-text"}),a[0]||(a[0]=l(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=t("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga IoT tizimlarining ko&#39;p qatlamli arxitekturasini, xususan, quyi apparat ta&#39;minoti — qurilmalar qatlami (Device/Perception Layer)ni chuqur o&#39;rgatish; analog va raqamli sensorlarning ishlash fizikasi, aktuatorlar (ijrochi mexanizmlar) turlari va mikrokontrollerning (Arduino, ESP32) tizimdagi boshqaruv rolini amaliy misollar bilan tushuntirish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar IoT ning 4 qatlamli modelini biladi; sensor va aktuator vazifalarini aniq ajrata oladi; analog va raqamli signallar farqini tushunadi; Arduino va ESP32 kabi apparat platformalarining asosiy xususiyatlarini sanay oladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>O&#39;tgan mavzuni takrorlash (IoT tushunchasi va sohalari): 10 daqiqa</li><li>Yangi mavzu: IoT ning 4 qatlamli modeli va qurilmalar qatlami: 20 daqiqa</li><li>Sensorlar (analog vs raqamli) va aktuatorlar (servo, rele, motor): 25 daqiqa</li><li>Mikrokontrollerlar (Arduino, ESP32, Raspberry Pi) arxitekturasi: 15 daqiqa</li><li>Nazorat savollari va dars xulosasi: 10 daqiqa</li></ul></li></ul><hr>",2))]),i("div",k,[i("h2",g,[r(o,{name:"file-text"}),a[3]||(a[3]=l(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=t('<h3 id="_1-iot-ning-4-qatlamli-arxitekturasi" tabindex="-1">1. IoT ning 4 qatlamli arxitekturasi <a class="header-anchor" href="#_1-iot-ning-4-qatlamli-arxitekturasi" aria-label="Permalink to &quot;1. IoT ning 4 qatlamli arxitekturasi&quot;">​</a></h3><p>Har qanday professional IoT tizimi 4 ta asosiy qatlamdan tashkil topadi:</p><ol><li><strong>Qurilmalar qatlami (Device / Perception Layer):</strong> Atrof-muhitni sezuvchi datchiklar (sensorlar), jismoniy harakat bajaruvchi asboblar (aktuatorlar) va ularni boshqaruvchi mikrokontrollerlar.</li><li><strong>Tarmoq qatlami (Network Layer):</strong> Ma&#39;lumotlarni simsiz (Wi-Fi, Bluetooth, LoRaWAN, GSM) yoki simli (Ethernet) yo&#39;l bilan shlyuzlar (Gateway) orqali uzatish.</li><li><strong>Ma&#39;lumotlarni qayta ishlash qatlami (Data Processing / Cloud Layer):</strong> Bulutli serverlar, ma&#39;lumotlar bazasi, filtrlash, tahlil va sun&#39;iy intellekt algoritmlari.</li><li><strong>Ilova qatlami (Application Layer):</strong> Foydalanuvchi ko&#39;radigan mobil ilova, veb-dashboard yoki avtomatlashtirilgan boshqaruv paneli.</li></ol><h3 id="_2-sensorlar-tizimning-ko-zi-va-qulog-i" tabindex="-1">2. Sensorlar (Tizimning &quot;Ko&#39;zi va Qulog&#39;i&quot;) <a class="header-anchor" href="#_2-sensorlar-tizimning-ko-zi-va-qulog-i" aria-label="Permalink to &quot;2. Sensorlar (Tizimning &quot;Ko&#39;zi va Qulog&#39;i&quot;)&quot;">​</a></h3><p>Sensorlar atrof-muhitdagi fizik, kimyoviy yoki mexanik ko&#39;rsatkichlarni sezib, ularni elektr signaliga (kuchlanish yoki tok) aylantiradi.</p><ul><li><strong>Analog sensorlar:</strong> Uzluksiz o&#39;zgarib turuvchi kuchlanish signali beradi (masalan, 0V dan 5V gacha). <ul><li><em>Misollar:</em> TMP36 (harorat), LDR (fotorezistor — yorug&#39;lik), MQ-2 (gaz miqdori), Potensiometr.</li><li>Mikrokontrollerdagi <strong>ADC (Analog-to-Digital Converter)</strong> uni 0 dan 1023 gacha raqamli qiymatga aylantiradi.</li></ul></li><li><strong>Raqamli sensorlar:</strong> Faqat 2 ta holatni (0 yoki 1, LOW yoki HIGH) yoki tayyor raqamli baytlarni uzatadi. <ul><li><em>Misollar:</em> PIR (harakat sezgichi — faqat &quot;harakat bor/yo&#39;q&quot;), tugma (Button), DHT11/DHT22 (raqamli harorat va namlik protokoli bilan).</li></ul></li></ul><h3 id="_3-aktuatorlar-tizimning-qo-li-va-ijrochi-mexanizmi" tabindex="-1">3. Aktuatorlar (Tizimning &quot;Qo&#39;li va Ijrochi Mexanizmi&quot;) <a class="header-anchor" href="#_3-aktuatorlar-tizimning-qo-li-va-ijrochi-mexanizmi" aria-label="Permalink to &quot;3. Aktuatorlar (Tizimning &quot;Qo&#39;li va Ijrochi Mexanizmi&quot;)&quot;">​</a></h3><p>Mikrokontroller buyrug&#39;i asosida elektr quvvatini jismoniy mexanik harakatga, yorug&#39;likka yoki tovushga aylantiruvchi qurilmalar:</p><ol><li><strong>Rele (Relay Module):</strong> Past kuchlanishli (5V) mikrokontroller signali orqali yuqori kuchlanishli (220V) maishiy asboblarni (chiroq, isitgich, nasos) xavfsiz yoqish/o&#39;chirish kaliti.</li><li><strong>Servo motor (Servomotor):</strong> O&#39;z o&#39;qini berilgan aniq burchakka (masalan, 0° dan 180° gacha) burish va ushlab turish imkonini beruvchi motor. Aqlli eshik qulflari, robot qo&#39;llar va avtomatik darchalar uchun.</li><li><strong>DC motor va Step motor:</strong> Uzluksiz aylanuvchi dvigatellar (konveyerlar, g&#39;ildiraklar) va aniq qadamli dvigatellar (3D printerlar).</li><li><strong>Solenoid klapan (Valve):</strong> Suv yoki gaz oqimini elektromagnit yordamida ochib-yopuvchi aqlli jo&#39;mrak.</li><li><strong>Indikatorlar:</strong> LED (yorug&#39;lik signali) va Buzzer (ovozli signal / signalizatsiya).</li></ol><h3 id="_4-mikrokontroller-tizimning-miyasi" tabindex="-1">4. Mikrokontroller (Tizimning &quot;Miyasi&quot;) <a class="header-anchor" href="#_4-mikrokontroller-tizimning-miyasi" aria-label="Permalink to &quot;4. Mikrokontroller (Tizimning &quot;Miyasi&quot;)&quot;">​</a></h3><p>Bitta yarimo&#39;tkazgichli kristall (chip) ichida joylashgan ixcham kompyuter:</p><ul><li><strong>Tarkibi:</strong> CPU (protsessor), RAM (tezkor xotira), Flash/ROM (dastur kodi saqlanadigan doimiy xotira), I/O (kirish-chiqish pinlari), Taymerlar, ADC, PWM va aloqa portlari (UART, SPI, I2C).</li><li><strong>Asosiy turlari:</strong><ul><li><em>Arduino Uno (ATmega328P):</em> 16 MHz, 32 KB xotira, 5V. O&#39;rganish va boshlang&#39;ich prototiplash uchun eng qulay. Tarmoq moduli yo&#39;q.</li><li><em>ESP8266 / ESP32:</em> 80-240 MHz, megabaytlab Flash xotira, 3.3V, o&#39;rnatilgan <strong>Wi-Fi va Bluetooth</strong>. Haqiqiy IoT loyihalari uchun eng mashhur mikrokontrollerlar.</li><li><em>Raspberry Pi:</em> Mikrokontroller emas, balki to&#39;liq <strong>Single Board Computer (SBC)</strong>. Unda to&#39;liq Linux (Raspberry Pi OS) ishlaydi, monitor va klaviatura ulanadi, yuqori darajadagi video tahlil va server vazifalarini bajaradi.</li></ul></li></ul><hr>',13))]),i("div",q,[i("h2",v,[r(o,{name:"file-text"}),a[6]||(a[6]=l(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=t('<h3 id="_1-topshiriq-sensor-va-aktuatorlarni-ajratish-oson" tabindex="-1">1-topshiriq. Sensor va aktuatorlarni ajratish (oson) <a class="header-anchor" href="#_1-topshiriq-sensor-va-aktuatorlarni-ajratish-oson" aria-label="Permalink to &quot;1-topshiriq. Sensor va aktuatorlarni ajratish (oson)&quot;">​</a></h3><p>Quyida berilgan qurilmalar ro&#39;yxatini ikki guruhga (Sensorlar va Aktuatorlar) ajrating:</p><ol><li>Fotorezistor (LDR); 2) Servomotor; 3) PIR harakat datchigi; 4) Elektromagnit rele; 5) Ovozli buzzer; 6) Tuproq namligi sensori.</li></ol><p><strong>Yechim:</strong></p><ul><li><strong>Sensorlar (Atrofni sezuvchi):</strong><ul><li><ol><li>Fotorezistor (LDR) — yorug&#39;lik darajasini o&#39;lchaydi;</li></ol></li><li><ol start="3"><li>PIR datchigi — inson harakatini sezadi;</li></ol></li><li><ol start="6"><li>Tuproq namligi sensori — tuproqdagi suv miqdorini aniqlaydi.</li></ol></li></ul></li><li><strong>Aktuatorlar (Ijrochi harakat):</strong><ul><li><ol start="2"><li>Servomotor — mexanik burchakka buriladi;</li></ol></li><li><ol start="4"><li>Elektromagnit rele — 220V tarmoqni ulaydi/uzadi;</li></ol></li><li><ol start="5"><li>Ovozli buzzer — ogohlantiruvchi tovush chiqaradi.</li></ol></li></ul></li></ul><h3 id="_2-topshiriq-rele-moduli-bilan-xavfsiz-boshqaruv-sxemasi-o-rta" tabindex="-1">2-topshiriq. Rele moduli bilan xavfsiz boshqaruv sxemasi (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-rele-moduli-bilan-xavfsiz-boshqaruv-sxemasi-o-rta" aria-label="Permalink to &quot;2-topshiriq. Rele moduli bilan xavfsiz boshqaruv sxemasi (o&#39;rta)&quot;">​</a></h3><p>Arduino mikrokontrolleri atigi 5V kuchlanish va bir necha o&#39;n milliamper tok bera oladi. Oddiy xona qandili (chirog&#39;i) esa 220V o&#39;zgaruvchan tok bilan ishlaydi. Nima uchun 220V li chiroqni to&#39;g&#39;ridan-to&#39;g&#39;ri Arduino piniga ulab bo&#39;lmaydi va ushbu muammo Rele (Relay) moduli orqali qanday hal etiladi?</p><p><strong>Yechim:</strong></p><ol><li><strong>Nega ulab bo&#39;lmaydi:</strong> Arduino mikrokontrollerining chiqish pinlari maksimal 5V va 20–40 mA tokka mo&#39;ljallangan. Agar unga 220V ulansa, mikrokontroller bir zumda yonib ketadi va elektr toki urish xavfi paydo bo&#39;ladi.</li><li><strong>Rele qanday yordam beradi:</strong><ul><li>Rele ichida elektromagnit g&#39;altak (katushka) va mexanik kontaktlar joylashgan.</li><li>Arduino relening 5V li kirishiga signal yuboradi: elektromagnit tortilib, alohida 220V zanjirdagi metall kontaktlarni bir-biriga jismonan yopishtiradi.</li><li>Natijada Arduino va 220V yuqori kuchlanish o&#39;rtasida <strong>galvanik izolyatsiya (to&#39;liq elektr xavfsizligi)</strong> ta&#39;minlanadi.</li></ul></li></ol><h3 id="_3-topshiriq-aqlli-to-siq-shlagbaum-loyihasi-uchun-komponentlar-tanlovi-qiyin" tabindex="-1">3-topshiriq. Aqlli to&#39;siq (Shlagbaum) loyihasi uchun komponentlar tanlovi (qiyin) <a class="header-anchor" href="#_3-topshiriq-aqlli-to-siq-shlagbaum-loyihasi-uchun-komponentlar-tanlovi-qiyin" aria-label="Permalink to &quot;3-topshiriq. Aqlli to&#39;siq (Shlagbaum) loyihasi uchun komponentlar tanlovi (qiyin)&quot;">​</a></h3><p>Avtoturargoh kirishida avtomobil yaqinlashganda raqamini aniqlamasdan, shunchaki masofani o&#39;lchab to&#39;siqni ochuvchi va yopuvchi sodda IoT shlagbaum tizimi qurilmoqda. Ushbu tizim uchun Sensor, Aktuator va Mikrokontroller tanlang hamda ularning o&#39;zaro ishlash algoritmini yozing.</p><p><strong>Yechim:</strong></p><ol><li><strong>Komponentlar tanlovi:</strong><ul><li><em>Sensor:</em> HC-SR04 ultratovush masofa sensori (avtomobil 1 metr masofaga kelganini aniqlash uchun).</li><li><em>Aktuator:</em> Servomotor (SG90 yoki MG995 — shlagbaum tayoqchasini 90 darajaga ko&#39;tarish uchun) va qizil/yashil LED indikatorlar.</li><li><em>Mikrokontroller:</em> Arduino Uno yoki ESP32.</li></ul></li><li><strong>Algoritm:</strong><ul><li><ol><li>Ultratovush sensori har 100 millisekundda masofani o&#39;lchaydi;</li></ol></li><li><ol start="2"><li>Agar masofa &gt; 100 sm bo&#39;lsa: Qizil LED yonadi, Servo 0° (to&#39;siq yopiq);</li></ol></li><li><ol start="3"><li>Agar masofa &lt;= 100 sm bo&#39;lsa (mashina keldi): Yashil LED yonadi, Servo 90° ga buriladi (to&#39;siq ko&#39;tariladi);</li></ol></li><li><ol start="4"><li>Mashina o&#39;tib ketib, masofa yana 100 sm dan oshgach, 5 soniya kutib, Servo yana 0° ga qaytadi (to&#39;siq yopiladi).</li></ol></li></ul></li></ol><hr>',14))]),i("div",y,[i("h2",b,[r(o,{name:"file-text"}),a[9]||(a[9]=l(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=t("<ol><li>IoT ning 4 qatlamli modelidagi birinchi (eng quyi) qatlam qanday ataladi? <ul><li><em>Javob:</em> Qurilmalar qatlami (Device yoki Perception Layer).</li></ul></li><li>Analog va raqamli sensorning asosiy farqi nimada? <ul><li><em>Javob:</em> Analog sensor uzluksiz o&#39;zgaruvchi kuchlanish (0–5V) beradi, raqamli sensor esa faqat diskret 0 va 1 (yoki tayyor raqamli paket) uzatadi.</li></ul></li><li>5V mikrokontroller signali bilan 220V elektr chiroqni xavfsiz boshqarish uchun qaysi aktuator ishlatiladi? <ul><li><em>Javob:</em> Rele moduli (Relay Module).</li></ul></li><li>ESP32 ning oddiy Arduino Uno dan eng asosiy ustunligi nimada? <ul><li><em>Javob:</em> ESP32 chipining ichida o&#39;rnatilgan Wi-Fi va Bluetooth modullari mavjud bo&#39;lib, protsessor tezligi va xotirasi ancha yuqori.</li></ul></li></ol><hr>",2))]),i("div",p,[i("h2",c,[r(o,{name:"file-text"}),a[12]||(a[12]=l(" Keng tarqalgan xatolar va ularning oldini olish ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#keng-tarqalgan-xatolar-va-ularning-oldini-olish","aria-label":'Permalink to "<Icon name="file-text" /> Keng tarqalgan xatolar va ularning oldini olish"'},"​",-1))]),a[14]||(a[14]=i("ul",null,[i("li",null,[i("strong",null,"Arduino va Raspberry Pi ni bitta toifaga kiritish:"),l(" O'quvchilar ko'pincha Raspberry Pi ni ham mikrokontroller deb o'ylashadi. Arduino — bu bitta dasturni qattiq siklda aylantiruvchi mikrokontroller; Raspberry Pi esa operatsion tizim (Linux) o'rnatilgan to'liq mini-kompyuterdir.")]),i("li",null,[i("strong",null,"Aktuatorlarni to'g'ridan-to'g'ri mikrokontroller pinidan quvvatlash:"),l(" Servo motor yoki kuchli dvigatellarni bevosita Arduino piniga ulash platani ishdan chiqarishi mumkin, chunki mikrokontroller pini bunday katta tok bera olmaydi. Motorlar har doim alohida tashqi quvvat manbaiga (External Power) ulanishi shart.")])],-1))])])}const I=n(m,[["render",z]]);export{P as __pageData,I as default};
